function e(n,r=0,t=2){return Math.abs(n).toLocaleString("en-IN",{minimumFractionDigits:r,maximumFractionDigits:t})}function i(n,r=2){return`${n<0?"-":""}\u20B9${e(n,0,r)}`}function s(n,r=2){let t=n<0?"-":"",o=Math.abs(n)/1e5;return`${t}\u20B9${o.toFixed(r)}L`}function a(n,r=2){let t=n<0?"-":"",o=Math.abs(n)/1e7;return`${t}\u20B9${o.toFixed(r)}Cr`}function b(n,r=2){let t=Math.abs(n);return t>=1e7?a(n,r):t>=1e5?s(n,r):i(n,r)}function u(n){return Math.abs(n)>=1e5}function c(n,r={}){let{abbreviated:t=!1,maximumFractionDigits:o=2}=r;return t&&u(n)?b(n,o):i(n,o)}export{i as a,b,u as c,c as d};
